// Test Inbound Catalog Payload for Manual Testing
return [
  {
    json: {
      catalog: [
        {
          sku: "TECH-CAM-4K-01",
          title: "UltraHD 4K Streaming Webcam with Ring Light",
          variant_id: "449102910291",
          cogs: 42.50,
          current_price: 79.99,
          map_price: 64.99,
          inventory_quantity: 420,
          target_margin_percent: 30
        },
        {
          sku: "TECH-MIC-USB-02",
          title: "Cardioid USB Condenser Microphone",
          variant_id: "449102910292",
          cogs: 30.00,
          current_price: 59.99,
          map_price: 49.99,
          inventory_quantity: 150,
          target_margin_percent: 35
        },
        {
          sku: "TECH-CAM-PREDATORY",
          title: "UltraHD 4K Streaming Webcam with Ring Light",
          variant_id: "449102910291",
          cogs: 42.50,
          current_price: 79.99,
          map_price: 64.99,
          inventory_quantity: 420,
          target_margin_percent: 30
        }
      ]
    }
  }
];

// Phase 1: Filter Node (Schema Gatekeeper)
// Verifies mandatory attributes: sku, title, cogs, current_price, variant_id, inventory_quantity.
const inputItems = $input.all();
const mandatoryFields = ['sku', 'title', 'cogs', 'current_price', 'variant_id', 'inventory_quantity'];

let rawCatalog = [];

for (const item of inputItems) {
  const json = item.json || {};
  const body = json.body || json;

  if (Array.isArray(body.catalog)) {
    rawCatalog.push(...body.catalog);
  } else if (Array.isArray(body)) {
    rawCatalog.push(...body);
  } else if (body.sku) {
    rawCatalog.push(body);
  } else if (typeof body.catalog === 'string') {
    try {
      const parsed = JSON.parse(body.catalog);
      if (Array.isArray(parsed)) rawCatalog.push(...parsed);
    } catch (e) {}
  }
}

// Resilient fallback for manual canvas testing
if (rawCatalog.length === 0) {
  rawCatalog = [
    {
      sku: "TECH-CAM-4K-01",
      title: "UltraHD 4K Streaming Webcam with Ring Light",
      variant_id: "449102910291",
      cogs: 42.50,
      current_price: 79.99,
      map_price: 64.99,
      inventory_quantity: 420,
      target_margin_percent: 30
    },
    {
      sku: "TECH-MIC-USB-02",
      title: "Cardioid USB Condenser Microphone",
      variant_id: "449102910292",
      cogs: 30.00,
      current_price: 59.99,
      map_price: 49.99,
      inventory_quantity: 150,
      target_margin_percent: 35
    },
    {
      sku: "TECH-CAM-PREDATORY",
      title: "UltraHD 4K Streaming Webcam with Ring Light",
      variant_id: "449102910291",
      cogs: 42.50,
      current_price: 79.99,
      map_price: 64.99,
      inventory_quantity: 420,
      target_margin_percent: 30
    }
  ];
}

const validItems = [];
const missingErrors = [];

for (const product of rawCatalog) {
  if (!product || typeof product !== 'object') continue;
  const missing = [];
  for (const field of mandatoryFields) {
    if (product[field] === undefined || product[field] === null || product[field] === '') {
      missing.push(field);
    }
  }

  if (missing.length > 0) {
    missingErrors.push({
      item_title: product.title || 'Unknown Title',
      missing_fields: missing
    });
  } else {
    validItems.push({
      ...product,
      cogs: Number(product.cogs),
      current_price: Number(product.current_price),
      map_price: Number(product.map_price || 0),
      inventory_quantity: Number(product.inventory_quantity)
    });
  }
}

if (missingErrors.length > 0 && validItems.length === 0) {
  return [{
    json: {
      is_valid: false,
      error: "INVALID_CATALOG_ITEM",
      missing_fields: missingErrors[0].missing_fields,
      error_details: missingErrors
    }
  }];
}

return validItems.map(item => ({ json: { ...item, is_valid: true } }));

